def logger(func):
    def wrapper(x):
        print("enter")
        result = func(x)
        print("exit")
        return result
    return wrapper

@logger
def process(x):
    print("body", x)
    return x + 1

print(process(4))

def repeat(times):
    def deco(func):
        def wrapper():
            for _ in range(times):
                print(func())
        return wrapper
    return deco

@repeat(2)
def ping():
    return "ping"

ping()

def bold(func):
    def wrapper():
        print("bold-in")
        func()
        print("bold-out")
    return wrapper

def italic(func):
    def wrapper():
        print("italic-in")
        func()
        print("italic-out")
    return wrapper

@bold
@italic
def doc():
    print("body")

doc()
